proguardAdditions.insert:

-keep class com.taptap.sdk.achievement.** { *; }
-keep interface com.taptap.sdk.achievement.** { *; }

-keep class com.taptap.sdk.achievement.internal.ue.** { *; }
-keepclassmembers class com.taptap.sdk.achievement.internal.ue.** { *; }

-keep @android.support.annotation.Keep class * { *; }
-keep @androidx.annotation.Keep class * { *; }

-keepclassmembers class com.taptap.sdk.achievement.** {
    public <methods>;
    public <fields>;
}

-keepclasseswithmembernames class * {
    native <methods>;
}

-keep class * implements com.taptap.sdk.achievement.** {
    public <methods>;
}

-keepattributes *Annotation*
-keepattributes Signature
-keepattributes Exceptions

-keepclassmembers class * implements java.io.Serializable {
    static final long serialVersionUID;
    private static final java.io.ObjectStreamField[] serialPersistentFields;
    private void writeObject(java.io.ObjectOutputStream);
    private void readObject(java.io.ObjectInputStream);
    java.lang.Object writeReplace();
    java.lang.Object readResolve();
}

-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile

-keep class com.taptap.sdk.kit.internal.enginebridge.** { *; }

gameActivityClassAdditions.insert:

public String routeToTapAchievement(String requestJson, EngineBridgeCallback callback) {
    try {
        return TapAchievementUERouter.route(this, requestJson, callback);
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapAchievement route error: " + e.getMessage(), e);
        return "{\"success\":false,\"message\":\"" + e.getMessage() + "\"}";
    }
}
